def text_features(text):
    text = "" if text is None else str(text)

    return (
        len(text),
        len(text.split()),
        sum(c.isdigit() for c in text),
        text.count("\n"),
        sum(c.isupper() for c in text),
        1.0 if not text else 0.0,
    )
